using System.Windows;using WPF_SEMANA02.Data;using WPF_SEMANA02.Models;namespace WPF_SEMANA02.Views;public partial class TransportistasWindow:Window{public TransportistasWindow(){InitializeComponent();dgTransportistas.ItemsSource=AppData.Transportistas;}private void Guardar_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(txtNombre.Text)||string.IsNullOrWhiteSpace(txtRuc.Text)){MessageBox.Show("Ingrese nombre y RUC.","Validación");return;}AppData.Transportistas.Add(new Transportista{Nombre=txtNombre.Text.Trim(),Ruc=txtRuc.Text.Trim(),Telefono=txtTelefono.Text.Trim()});MessageBox.Show("Transportista registrado correctamente.","Información");Limpiar();}private void Limpiar_Click(object s,RoutedEventArgs e)=>Limpiar();private void Limpiar(){txtNombre.Clear();txtRuc.Clear();txtTelefono.Clear();}private void Volver_Click(object s,RoutedEventArgs e)=>Close();}
